// --- commerce: orders, catalogue
// ---------------------------------------------------------------------------------

/** `#/schemas/OrderStatus` rebuilt as a class enum; labels are the orders namespace keys. */
export class OrderStatus extends Enum<OrderStatus> {
  static readonly PendingPayment = OrderStatus.case("pending_payment", {
    label: I18n.orders.status.pending_payment,
    color: "warning",
  });
  static readonly Paid = OrderStatus.case("paid", {
    label: I18n.orders.status.paid,
    color: "success",
  });
  static readonly Cancelled = OrderStatus.case("cancelled", {
    label: I18n.orders.status.cancelled,
    color: "default",
  });
  static readonly Expired = OrderStatus.case("expired", {
    label: I18n.orders.status.expired,
    color: "default",
  });
}

/** `#/schemas/OrderTotals` (served from 2027-03-01, the pinned version). */
export const OrderTotals = z.object({
  currency: z.string().length(3),
  subtotalMinor: z.number().int().min(0),
  adjustments: z.array(
    z.object({ code: z.string(), label: z.string(), amountMinor: z.number().int() }),
 ),
  totalMinor: z.number().int().min(0),
});

/** `#/schemas/OrderView`. */
export const OrderView = z.object({
  id: z.string(),
  status: OrderStatus.schema,
  totals: OrderTotals,
  lines: z.array(
    z.object({
      variantId: z.string(),
      quantity: z.number().int(),
      unitPriceMinor: z.number().int(),
    }),
 ),
  createdAt: z.iso.datetime(),
});

/** `#/schemas/OrdersTodayOutput`. */
export const OrdersTodayOutput = z.object({
  count: z.number().int(),
  revenueMinor: z.number().int(),
  currency: z.string(),
  hourly: z.array(z.number().int()).length(24),
});

/** `#/schemas/VariantHit`. */
export const VariantHit = z.object({
  variantId: z.string(),
  productId: z.string(),
  sku: z.string(),
  title: z.string(),
  trackInventory: z.boolean(),
});

/** `#/schemas/OrderPaidV1`: the `orders.order.paid.v1` payload. */
export const OrderPaidV1 = z.object({
  orderId: z.string(),
  customerId: z.string(),
  paymentId: z.string(),
  totalMinor: z.number().int(),
  currency: z.string().length(3),
});

/** Everything this build uses from `@acme/service-commerce`. */
export const Commerce = {
  actions: {
    CreateOrder: actionRef("orders.order.create", {
      input: z.object({
        lines: z
          .array(z.object({ variantId: z.string(), quantity: z.number().int().min(1) }))
          .min(1)
          .max(100),
        extensions: z
          .object({
            loyalty: z.object({ redeemPoints: z.number().int().min(1).max(1_000_000) }).optional(),
          })
          .default({}),
      }),
      output: z.object({
        orderId: z.string(),
        status: OrderStatus.schema,
        totals: OrderTotals,
        paymentClientSecret: z.string(),
      }),
      http: { method: HttpMethod.Post, path: "/orders" },
      risk: Risk.L1,
    }),
    CancelOrder: actionRef("orders.order.cancel", {
      input: z.object({ orderId: z.string() }),
      output: z.object({ orderId: z.string(), status: OrderStatus.schema }),
      http: { method: HttpMethod.Put, path: "/orders/:orderId/cancel" },
      risk: Risk.L2,
      ux: { confirm: I18n.orders.order.cancel_confirm, success: I18n.orders.order.cancelled },
    }),
  },
  queries: {
    GetOrder: queryRef("orders.order.get", {
      input: z.object({ orderId: z.string() }),
      output: OrderView,
      http: { method: HttpMethod.Get, path: "/orders/:orderId" },
    }),
    ListOrders: queryRef("orders.order.list", {
      input: z.object({
        cursor: z.string().optional(),
        limit: z.number().int().min(1).max(100).default(20),
        status: OrderStatus.schema.optional(),
      }),
      output: z.object({
        items: z.array(OrderView),
        nextCursor: z.string().optional(),
        hasMore: z.boolean(),
      }),
      http: { method: HttpMethod.Get, path: "/orders" },
    }),
    OrdersToday: queryRef("orders.order.stats_today", {
      input: z.object({}),
      output: OrdersTodayOutput,
    }),
    GetVariantByBarcode: queryRef("catalogue.variant.get_by_barcode", {
      input: z.object({ barcode: z.string().regex(/^\d{8,14}$/) }),
      output: VariantHit,
      http: { method: HttpMethod.Get, path: "/variants/by-barcode/:barcode" },
    }),
  },
  permissions: {
    Order: {
      create: permissionRef("orders.order.create"),
      read: permissionRef("orders.order.read"),
      cancel: permissionRef("orders.order.cancel"),
    },
    Product: { read: permissionRef("catalogue.product.read") },
  },
  overrides: {
    RevenueSparkline: overridePointRef("orders.revenue_sparkline", {
      props: OrdersTodayOutput,
      required: true,
    }),
    OrderStatusBadge: overridePointRef("orders.order_status_badge", {
      props: z.object({ status: OrderStatus.schema, compact: z.boolean() }),
    }),
  },
  widgets: { RevenueToday: widgetRef("orders.revenue_today") },
  events: { OrderPaid: eventRef("orders.order.paid.v1", { payload: OrderPaidV1 }) },
  refusals: {
    variant_unavailable: refusalRef("catalogue.variant_unavailable", {
      message: I18n.catalogue.refusals.variant_unavailable,
    }),
    variant_not_found: refusalRef("catalogue.variant_not_found", {
      message: I18n.catalogue.refusals.variant_not_found,
    }),
    insufficient_stock: refusalRef("inventory.insufficient_stock", {
      message: I18n.inventory.refusals.insufficient_stock,
    }),
  },
  enums: { OrderStatus },
} as const;

