// -------------------------------------------------------------------------------------

/** `messages.NotificationKind` rebuilt as a class enum; labels are the messages namespace keys. */
export class NotificationKind extends Enum<NotificationKind> {
  /** A customer's order was paid; data carries the order id, total and line count. */
  static readonly OrderPaid = NotificationKind.case("order_paid", {
    label: I18n.messages.notification_kind.order_paid,
  });
}

/**
 * `#/schemas/NotificationView`: one inbox entry; the app renders the kind's label with `data`.
 */
export const NotificationView = z.object({
  id: z.string(),
  kind: NotificationKind.schema,
  data: z.record(z.string(), z.union([z.string(), z.number()])),
  createdAt: z.iso.datetime(),
  readAt: z.iso.datetime().nullable(),
});

/** Everything this build uses from `@acme/service-notifications`. */
export const Notifications = {
  actions: {
    MarkNotificationRead: actionRef("messages.notification.mark_read", {
      input: z.object({ notificationId: z.string() }),
      output: NotificationView,
      http: { method: HttpMethod.Put, path: "/notifications/:notificationId/read" },
      risk: Risk.L0,
    }),
  },
  queries: {
    /** `unread` counts the actor's whole inbox, not the page. */
    ListNotifications: queryRef("messages.notification.list", {
      input: z.object({
        cursor: z.string().optional(),
        limit: z.number().int().min(1).max(100).default(20),
        unreadOnly: z.boolean().default(false),
      }),
      output: z.object({
        items: z.array(NotificationView),
        nextCursor: z.string().optional(),
        hasMore: z.boolean(),
        unread: z.number().int().nonnegative(),
      }),
      http: { method: HttpMethod.Get, path: "/notifications" },
    }),
  },
  permissions: {
    Notification: {
      read: permissionRef("messages.notification.read"),
      update: permissionRef("messages.notification.update"),
    },
  },
  events: {
    /** Broadcast to the signed-in principal's own sessions only; never delivered to a service. */
    NotificationCreated: eventRef("messages.notification.created.v1", {
      payload: z.object({
        notificationId: z.string(),
        principalId: z.string(),
        kind: NotificationKind.schema,
      }),
      channel: "principal.{principalId}.notifications",
    }),
  },
  refusals: {
    notification_not_found: refusalRef("messages.notification_not_found", {
      message: I18n.messages.refusals.notification_not_found,
    }),
  },
  enums: { NotificationKind },
} as const;

